"""Merge overlapping / touching integer intervals."""

from __future__ import annotations


def _as_pair(item):
    """Validate one interval and return it as a list [start, end]."""
    try:
        start, end = item
    except (TypeError, ValueError):
        raise ValueError(f"interval must be a pair [start, end], got {item!r}")
    for value in (start, end):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(f"interval bounds must be integers, got {item!r}")
    if start > end:
        raise ValueError(f"reversed interval: [{start}, {end}]")
    return [start, end]


def merge_intervals(intervals):
    """Merge integer intervals that overlap or touch, sorted ascending.

    >>> merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]])
    [[1, 6], [8, 10], [15, 18]]
    >>> merge_intervals([[1, 4], [4, 5]])   # touching endpoints
    [[1, 5]]
    >>> merge_intervals([[5, 5], [1, 2]])
    [[1, 2], [5, 5]]
    >>> merge_intervals([])
    []

    Touching = the pairs share an endpoint (``start <= previous end``).
    Output is sorted ascending by start; the input is never mutated;
    reversed pairs (start > end) raise ValueError.
    """
    pairs = [_as_pair(item) for item in intervals]
    pairs.sort(key=lambda p: (p[0], p[1]))

    merged = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

