"""Tests for solution.merge_intervals (stdlib unittest, no pytest needed)."""

import copy
import doctest
import unittest

from solution import merge_intervals


class TestMergeIntervals(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([[3, 7]]), [[3, 7]])

    def test_point_interval(self):
        self.assertEqual(merge_intervals([[2, 2]]), [[2, 2]])

    def test_no_overlap_sorted_input(self):
        self.assertEqual(
            merge_intervals([[1, 2], [4, 5], [9, 10]]),
            [[1, 2], [4, 5], [9, 10]],
        )

    def test_unsorted_input_is_sorted(self):
        self.assertEqual(
            merge_intervals([[15, 18], [1, 3], [8, 10]]),
            [[1, 3], [8, 10], [15, 18]],
        )

    def test_overlap_merges(self):
        self.assertEqual(
            merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]),
            [[1, 6], [8, 10], [15, 18]],
        )

    def test_touching_endpoints_merge(self):
        self.assertEqual(merge_intervals([[1, 4], [4, 5]]), [[1, 5]])

    def test_touching_out_of_order_merge(self):
        self.assertEqual(merge_intervals([[4, 5], [1, 4]]), [[1, 5]])

    def test_chain_of_touching(self):
        self.assertEqual(
            merge_intervals([[10, 11], [7, 8], [8, 9], [9, 10]]),
            [[7, 11]],
        )

    def test_nested_interval_swallowed(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 2], [1, 2]]), [[1, 2]])

    def test_one_unit_gap_stays_separate(self):
        # no shared endpoint, so not "touching"
        self.assertEqual(merge_intervals([[1, 2], [3, 4]]), [[1, 2], [3, 4]])

    def test_negatives(self):
        self.assertEqual(merge_intervals([[-5, -3], [-3, 0], [2, 2]]), [[-5, 0], [2, 2]])

    def test_crossing_zero(self):
        self.assertEqual(merge_intervals([[-2, 1], [1, 5]]), [[-2, 5]])

    def test_contained_then_extended(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 9], [9, 12]]), [[1, 12]])

    def test_input_not_mutated(self):
        src = [[15, 18], [1, 3], [2, 6]]
        snapshot = copy.deepcopy(src)
        merge_intervals(src)
        self.assertEqual(src, snapshot)
        self.assertIsInstance(src[0], list)

    def test_input_list_pairs_multiple_calls_stable(self):
        src = [[1, 3], [3, 4]]
        first = merge_intervals(src)
        second = merge_intervals(src)
        self.assertEqual(first, second)
        self.assertEqual(first, [[1, 4]])
        # returned inner lists are fresh objects
        self.assertIsNot(first[0], src[0])

    def test_output_not_sharing_objects_with_input(self):
        src = [[1, 2], [2, 3]]
        out = merge_intervals(src)
        out[0][1] = 999
        self.assertEqual(src, [[1, 2], [2, 3]])

    def test_accepts_tuples(self):
        self.assertEqual(merge_intervals([(1, 4), (4, 5), (8, 9)]), [[1, 5], [8, 9]])

    def test_accepts_iterator(self):
        self.assertEqual(merge_intervals(iter([[5, 6], [1, 2]])), [[1, 2], [5, 6]])

    def test_accepts_generator(self):
        gen = (pair for pair in [[5, 6], [6, 7]])
        self.assertEqual(merge_intervals(gen), [[5, 7]])

    def test_reversed_pair_raises(self):
        with self.assertRaises(ValueError):
            merge_intervals([[3, 1]])

    def test_reversed_pair_raises_even_when_mergeable(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 5], [6, 4]])

    def test_error_message_names_the_pair(self):
        with self.assertRaisesRegex(ValueError, r"\[3, 1\]"):
            merge_intervals([[3, 1]])

    def test_bad_shape_raises_valueerror(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1, 2, 3]])
        with self.assertRaises(ValueError):
            merge_intervals([[1]])
        with self.assertRaises(ValueError):
            merge_intervals([5])

    def test_non_integer_bounds_raise_valueerror(self):
        with self.assertRaises(ValueError):
            merge_intervals([[1.0, 3]])
        with self.assertRaises(ValueError):
            merge_intervals([["1", "3"]])
        with self.assertRaises(ValueError):
            merge_intervals([[True, 3]])

    def test_large_values(self):
        big = 10 ** 18
        self.assertEqual(merge_intervals([[big, big + 5], [big + 5, big + 9]]),
                         [[big, big + 9]])

    def test_wide_random_agreement_with_oracle(self):
        import random

        random.seed(20261108)

        def oracle(pairs):
            # merge only when intervals overlap or share an endpoint
            out = []
            for a, b in sorted(pairs):
                if out and a <= out[-1][1]:
                    out[-1][1] = max(out[-1][1], b)
                else:
                    out.append([a, b])
            return out

        for _ in range(300):
            pairs = []
            for _ in range(random.randint(0, 8)):
                a = random.randint(-20, 20)
                b = a + random.randint(0, 6)
                pairs.append([a, b])
            self.assertEqual(merge_intervals(pairs), oracle(pairs), pairs)


def load_tests(loader, tests, ignore):
    tests.addTests(doctest.DocTestSuite(__import__("solution")))
    return tests


if __name__ == "__main__":
    unittest.main(verbosity=2)

