"""Tests for ledger.total (stdlib unittest, no third-party deps)."""

import unittest
from decimal import Decimal

import ledger
from ledger import total


class TotalTests(unittest.TestCase):
    def test_basic_sum(self):
        self.assertEqual(total(["1.10", "2.20", "3.30"]), Decimal("6.60"))

    def test_exact_decimal_no_float_error(self):
        self.assertEqual(total(["0.1", "0.2"]), Decimal("0.3"))

    def test_signed_amounts(self):
        self.assertEqual(total(["-5.50", "2.25", "-0.25"]), Decimal("-3.50"))
        self.assertEqual(total(["+1.5", "-1.5"]), Decimal("0.0"))

    def test_blank_lines_ignored(self):
        self.assertEqual(total(["1", "", "   ", "\t"]), Decimal("1"))
        self.assertEqual(total(["1", "\n", "2"]), Decimal("3"))

    def test_blank_and_signed_lines(self):
        self.assertEqual(total(["", "  10.005 ", "-0.005", ""]), Decimal("10.000"))

    def test_string_input_with_lines(self):
        self.assertEqual(total("1.5\n\n-2.5\n"), Decimal("-1.0"))

    def test_empty_input(self):
        self.assertEqual(total([]), Decimal(0))
        self.assertEqual(total(""), Decimal(0))

    def test_malformed_raises_value_error(self):
        for bad in ["abc", "1.2.3", "1,000", "12abc", "--1", "$5", "1e", "1/2"]:
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    total(["1", bad])

    def test_malformed_reports_offending_value(self):
        with self.assertRaises(ValueError) as ctx:
            total(["1", "oops"])
        self.assertIn("oops", str(ctx.exception))

    def test_accepts_non_string_rows(self):
        self.assertEqual(total([1, 2, "-3"]), Decimal("0"))

    def test_result_type_is_decimal(self):
        self.assertIsInstance(total(["1.1", "2.2"]), Decimal)

    def test_public_name_preserved(self):
        self.assertTrue(callable(ledger.total))

    def test_no_float_rounding_on_large_sum(self):
        rows = ["0.01"] * 1000
        self.assertEqual(total(rows), Decimal("10.00"))


if __name__ == "__main__":
    unittest.main(verbosity=2)
